import java.util.*;

class Solution {
  public void wallsAndGates(int[][] rooms) {
    int m = rooms.length, n = rooms[0].length;
    Deque<int[]> q = new ArrayDeque<>();
    for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) if (rooms[i][j] == 0) q.add(new int[] {i, j});
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    // multi-source BFS from every gate: the first visit is the shortest distance
    while (!q.isEmpty()) {
      int[] c = q.poll();
      for (int[] d : dirs) {
        int x = c[0] + d[0], y = c[1] + d[1];
        if (x < 0 || y < 0 || x >= m || y >= n || rooms[x][y] != Integer.MAX_VALUE) continue;
        rooms[x][y] = rooms[c[0]][c[1]] + 1;
        q.add(new int[] {x, y});
      }
    }
  }
}
